#!/bin/bash
# Builds "EQing Factory.app":
#   1. Rust core (with autoeq-c orig compiled in) → libeqing_core.a
#   2. Swift bindings generated by uniFFI
#   3. SwiftUI app (Swift Package Manager) → build/EQing Factory.app
# Requirements: Xcode tools (xcode-select --install) and Rust (https://rustup.rs).
# Usage: mac/scripts/build_mac.sh [--open | --core-only]
#   --core-only: steps 1 and 2 only (after a change to the Rust code, before relaunching from Xcode)
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
CORE="$ROOT/core"
MAC="$ROOT/mac"
export MACOSX_DEPLOYMENT_TARGET=14.0

command -v cargo >/dev/null || { echo "Rust not found: install it from https://rustup.rs"; exit 1; }
[ "${1:-}" = "--core-only" ] || command -v swift >/dev/null || { echo "Swift not found: run 'xcode-select --install'"; exit 1; }

echo "==> Rust core"
cd "$CORE"
cargo build --release --features bindgen
TARGET_DIR="${CARGO_TARGET_DIR:-$CORE/target}"

echo "==> Swift bindings (uniFFI)"
GEN="$(mktemp -d)"
"$TARGET_DIR/release/uniffi-bindgen" generate \
    --library "$TARGET_DIR/release/libeqing_core.dylib" --language swift --out-dir "$GEN" >/dev/null
mkdir -p "$MAC/Sources/eqing_coreFFI" "$MAC/Sources/EQingFactory/Generated" "$MAC/lib"
cp "$GEN/eqing_coreFFI.h" "$MAC/Sources/eqing_coreFFI/"
cp "$GEN/eqing_core.swift" "$MAC/Sources/EQingFactory/Generated/"
cat > "$MAC/Sources/eqing_coreFFI/module.modulemap" <<'MAP'
module eqing_coreFFI {
    header "eqing_coreFFI.h"
    link "eqing_core"
    export *
}
MAP
# static library only: the app bundles no dylib
rm -f "$MAC/lib/"*
cp "$TARGET_DIR/release/libeqing_core.a" "$MAC/lib/"
if [ "${1:-}" = "--core-only" ]; then echo "==> Core and bindings up to date (relaunch the app from Xcode)"; exit 0; fi

echo "==> SwiftUI app"
cd "$MAC"
swift build -c release
BIN="$(swift build -c release --show-bin-path)/EQingFactory"

APP="$ROOT/build/EQing Factory.app"
rm -rf "$APP"
mkdir -p "$APP/Contents/MacOS" "$APP/Contents/Resources"
cp "$BIN" "$APP/Contents/MacOS/EQingFactory"
cp "$MAC/Info.plist" "$APP/Contents/Info.plist"
codesign --force --sign - "$APP" >/dev/null 2>&1 || echo "(ad hoc signing failed; the app is still usable locally)"

echo "==> Ready: $APP"
if [ "${1:-}" = "--open" ]; then open "$APP"; fi
